macro_rules! panic_on_err {
    ($expr:expr) => {
        match $expr {
            Ok(x) => x,
            Err(err) => panic!("{err}"),
        }
    };
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub(crate) struct RouteId(u32);

/// The router type for composing handlers and services.
#[must_use]
pub struct Router<S = ()> {
    path_router: PathRouter<S, false>,
    fallback_router: PathRouter<S, true>,
    default_fallback: bool,
    catch_all_fallback: Fallback<S>,
    path_rules: PathRules,
    method_rules: MethodRules,
    prefix_rules: PrefixRules,
    param_rules: ParamRules,
    json_rules: JsonRules,
    form_rules: FormRules,
    query_rules: QueryRules,
    nest_rules: NestRules,
    header_rules: HeaderRules,
    fallback_rules: FallbackRules,
    merge_rules: MergeRules,
    match_rules: MatchRules,
    layer_rules: LayerRules,
    allow_rules: AllowRules,
    body_rules: BodyRules,
    service_rules: ServiceRules,
}

impl<S> Clone for Router<S> {
    fn clone(&self) -> Self {
        Self {
            path_router: self.path_router.clone(),
            fallback_router: self.fallback_router.clone(),
            default_fallback: self.default_fallback,
            catch_all_fallback: self.catch_all_fallback.clone(),
            path_rules: self.path_rules,
            method_rules: self.method_rules,
            prefix_rules: self.prefix_rules,
            param_rules: self.param_rules,
            json_rules: self.json_rules,
            form_rules: self.form_rules,
            query_rules: self.query_rules,
            nest_rules: self.nest_rules,
            header_rules: self.header_rules,
            fallback_rules: self.fallback_rules,
            merge_rules: self.merge_rules,
            match_rules: self.match_rules,
            layer_rules: self.layer_rules,
            allow_rules: self.allow_rules,
            body_rules: self.body_rules,
            service_rules: self.service_rules,
        }
    }
}

impl<S> Default for Router<S>
where
    S: Clone + Send + Sync + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

